import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"否","description":"周易正义 - 否","frontmatter":{"title":"否","description":"周易正义 - 否"},"headers":[],"relativePath":"zh/classics/zhengyi/012.md","filePath":"zh/classics/zhengyi/012.md"}'),l={name:"zh/classics/zhengyi/012.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>天地否</p></blockquote><blockquote><p>卦辞：否之匪人，不利君子贞，大往小来。</p></blockquote><blockquote><p>彖曰：否，之匪人，不利君子贞。大往小来，则是天地不交而万物不通也，上下不交而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子，小人道长，君子道消也。</p></blockquote><h1 id="否" tabindex="-1">否 <a class="header-anchor" href="#否" aria-label="Permalink to “否”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“否之匪人”者，言否闭之世，非是人道交通之时，故云“匪人”。“不利君子贞”者，由小人道长，君子道消，故不利君子为正也。阳气往而阴气来，故云“大往小来”。阳主生息，故称“大”；阴主消耗，故称“小”。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="否之匪人-不利君子贞-大往小来-则是天地不交-而万物不通也-上下不交-而天下无邦也。内阴而外阳-内柔而外刚-内小人而外君子-小人道长-君子道消也。-​" tabindex="-1">“否之匪人，不利君子贞，大往小来”，则是天地不交，而万物不通也；上下不交，而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子，小人道长，君子道消也。 ​ <a class="header-anchor" href="#否之匪人-不利君子贞-大往小来-则是天地不交-而万物不通也-上下不交-而天下无邦也。内阴而外阳-内柔而外刚-内小人而外君子-小人道长-君子道消也。-​" aria-label="Permalink to ““否之匪人，不利君子贞，大往小来”，则是天地不交，而万物不通也；上下不交，而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子，小人道长，君子道消也。 ​”">​</a></h3><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“上下不交而天下无邦”者，与泰卦反也。《泰卦》云“上下交而其志同”，此应云“上下不交则其志不同”也。非但其志不同，上下乖隔，则邦国灭亡，故变云“天下无邦”也。“内柔而外刚”者，欲取否塞之义，故内至柔弱，外御刚彊，所以否闭。若欲取“通泰”之义，则云“内健”“外顺”。各随义为文，故此云“刚柔”，不云：“健顺”。</p><h3 id="《象》曰-天地不交-否。君子以俭德辟难-不可荣以禄。-​" tabindex="-1">《象》曰：天地不交，否。君子以俭德辟难，不可荣以禄。 ​ <a class="header-anchor" href="#《象》曰-天地不交-否。君子以俭德辟难-不可荣以禄。-​" aria-label="Permalink to “《象》曰：天地不交，否。君子以俭德辟难，不可荣以禄。 ​”">​</a></h3><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“君子以俭德辟难”者，言君子於此否塞之时，以节俭为德，辟其危难，不可荣华其身，以居禄位。此若据诸侯公卿言之，辟其群小之难，不可重受官赏；若据王者言之，谓节俭为德，辟其阴阳已运之难，不可重自荣华而骄逸也。</p><h2 id="初六-拔茅茹-以其汇-贞-吉亨。-​" tabindex="-1">初六：拔茅茹，以其汇，贞，吉亨。 ​ <a class="header-anchor" href="#初六-拔茅茹-以其汇-贞-吉亨。-​" aria-label="Permalink to “初六：拔茅茹，以其汇，贞，吉亨。 ​”">​</a></h2><p>王弼：居否之初，处顺之始，为类之首者也。顺非健也，何可以征？居否之时，动则入邪，三阴同道，皆不可进。故“茅茹”以类，贞而不谄，则“吉亨”。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“拔茅茹”者，以居否之初，处顺之始，未可以动，动则入邪，不敢前进。三阴皆然，犹若拔茅牵连其根相茹也。己若不进，馀皆从之，故云“拔茅茹”也。“以其汇”者，以其同类，共皆如此。“贞吉亨”者，守正而居志在於君，乃得吉而亨通。</p><h3 id="《象》曰-拔茅贞吉-志在君也。-​" tabindex="-1">《象》曰：拔茅贞吉，志在君也。 ​ <a class="header-anchor" href="#《象》曰-拔茅贞吉-志在君也。-​" aria-label="Permalink to “《象》曰：拔茅贞吉，志在君也。 ​”">​</a></h3><p>王弼：志在於君，故不苟进。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志在君”者，释“拔茅贞吉”之义。所以居而守正者，以其志意在君，不敢怀谄苟进，故得“吉亨”也。此假外物以明人事。</p><h2 id="六二-包承-小人吉-大人否-亨。-​" tabindex="-1">六二：包承，小人吉，大人否，亨。 ​ <a class="header-anchor" href="#六二-包承-小人吉-大人否-亨。-​" aria-label="Permalink to “六二：包承，小人吉，大人否，亨。 ​”">​</a></h2><p>王弼：居“否”之世，而得其位，用其至顺，包承於上，小人路通，内柔外刚，大人“否”之，其道乃“亨”。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“包承”者，居“否”之世而得其位，用其志顺，包承於上。“小人吉”者，否闭之时，小人路通，故於小人为吉也。“大人否亨”者，若大人用此“包承”之德，能否闭小人之“吉”，其道乃亨。</p><h3 id="《象》曰-大人否亨-不乱群也。-​" tabindex="-1">《象》曰：“大人否亨”，不乱群也。 ​ <a class="header-anchor" href="#《象》曰-大人否亨-不乱群也。-​" aria-label="Permalink to “《象》曰：“大人否亨”，不乱群也。 ​”">​</a></h3><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此释所以大人“否亨”之意，良由否闭小人，防之以得其道，小人虽盛，不敢乱群，故言“不乱群”也。</p><h2 id="六三-包羞。-​" tabindex="-1">六三：包羞。 ​ <a class="header-anchor" href="#六三-包羞。-​" aria-label="Permalink to “六三：包羞。 ​”">​</a></h2><p>王弼：俱用小道以承其上，而但不当，所以“包羞”也。</p><h3 id="《象》曰-包羞-位不当也。-​" tabindex="-1">《象》曰：“包羞”，位不当也。 ​ <a class="header-anchor" href="#《象》曰-包羞-位不当也。-​" aria-label="Permalink to “《象》曰：“包羞”，位不当也。 ​”">​</a></h3><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“包羞”者，言群阴俱用小人之道包承於上，以失位不当，所包承之事，唯羞辱己。</p><h2 id="九四-有命无咎。畴离祉。-​" tabindex="-1">九四：有命无咎。畴离祉。 ​ <a class="header-anchor" href="#九四-有命无咎。畴离祉。-​" aria-label="Permalink to “九四：有命无咎。畴离祉。 ​”">​</a></h2><p>王弼：夫处“否”而不可以有命者，以所应者小人也。有命於小人，则消君子之道者也。今初志在君，处乎穷下，故可以有命无咎而畴丽福也。畴谓初也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“有命无咎”者，九四处否之时，其阴爻皆是小人。若有命於小人，则君子道消也。今初六志在於君，守正不进，处于穷下。今九四有命命之，故“无咎”。“畴离祉”者，畴谓畴匹，谓初六也。离，丽也。丽谓附著也。言九四命初，身既无咎，初既被命，附依祉福，言初六得福也。</p><h3 id="《象》曰-有命无咎-志行也。-​" tabindex="-1">《象》曰：“有命无咎”，志行也。 ​ <a class="header-anchor" href="#《象》曰-有命无咎-志行也。-​" aria-label="Permalink to “《象》曰：“有命无咎”，志行也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“有命无咎”之义，所以九四有命，得无咎者，由初六志意得行，守正而应於上，故九四之命得无咎。</p><h2 id="九五-休否-大人吉。其亡其亡-系于苞桑。-​" tabindex="-1">九五：休否，大人吉。其亡其亡，系于苞桑。 ​ <a class="header-anchor" href="#九五-休否-大人吉。其亡其亡-系于苞桑。-​" aria-label="Permalink to “九五：休否，大人吉。其亡其亡，系于苞桑。 ​”">​</a></h2><p>王弼：居尊得位，能休否道者也。施否於小人，否之休也。唯大人而后能然，故曰“大人吉”也。处君子道消之时，已居尊位，何可以安？故心存将危，乃得固也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>“九五休否”至“系于苞桑”。○正义曰：“休否”者，休，美也。谓能行休美之事於否塞之时，能施此否闭之道，遏绝小人，则是“否”之休美者也，故云“休否”。“大人吉”者，唯大人乃能如此而得吉也，若其凡人，则不能。“其亡其亡，系于苞桑”者，在道消之世，居於尊位而遏小人，必近危难，须恒自戒慎其意，常惧其危亡，言丁宁戒慎如此也。“系于苞桑”者，苞，本也。凡物系于桑之苞本则牢固也。若能“其亡其亡”，以自戒慎，则有“系于苞桑”之固，无倾危也。○注“心存将危”。○正义曰：“心存将危”，解“其亡其亡”之义。身虽安静，心意常存将有危难，但念“其亡其亡”，乃得固者，即“系于苞桑”也。必云“苞桑”者；取会韵之义。又桑之为物，其根众也。众，则牢固之义。</p><h3 id="《象》曰-大人之吉-位正当也。-​" tabindex="-1">《象》曰：大人之吉，位正当也。 ​ <a class="header-anchor" href="#《象》曰-大人之吉-位正当也。-​" aria-label="Permalink to “《象》曰：大人之吉，位正当也。 ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“大人吉”之义，言九五居尊得位，正所以当遏绝小人得其吉。</p><h2 id="上九-倾否-先否后喜。-​" tabindex="-1">上九：倾否，先否后喜。 ​ <a class="header-anchor" href="#上九-倾否-先否后喜。-​" aria-label="Permalink to “上九：倾否，先否后喜。 ​”">​</a></h2><p>王弼：先倾后通，故“后喜”也。始以倾为“否”，后得通乃喜。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：处否之极，否道已终，此上九能倾毁其否，故曰“倾否”也。“先否后喜”者，否道未倾之时，是“先否”之道；否道巳倾之后，其事得通，故曰“后有喜”也。</p><h3 id="《象》曰-否终则倾-何可长也-​" tabindex="-1">《象》曰：否终则倾，何可长也？ ​ <a class="header-anchor" href="#《象》曰-否终则倾-何可长也-​" aria-label="Permalink to “《象》曰：否终则倾，何可长也？ ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：释“倾否”之义。否道巳终，通道将至。故“否”之终极，则倾损其否，何得长久？故云“何可长也”。</p>',54)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
